#!/usr/bin/env node
/**
 * Export environment configuration to documentation wiki
 */

const fs = require('fs');
const http = require('http');

// Read and parse .env.test file
const envFile = fs.readFileSync('.env.test', 'utf8');

const envVars = {};
envFile.split('\n').forEach(line => {
  // Skip empty lines and comments
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const equalsIndex = line.indexOf('=');
    if (equalsIndex > 0) {
      const key = line.substring(0, equalsIndex);
      const value = line.substring(equalsIndex + 1);
      envVars[key] = value;
    }
  }
});

// Prepare the POST data
const postData = JSON.stringify(envVars, null, 2);

console.log('Environment variables to export:');
console.log(postData);
console.log('\nSending to documentation wiki...\n');

// Configure the POST request
const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

// Make the HTTP request
const req = http.request(options, (res) => {
  console.log(`Status Code: ${res.statusCode}`);

  res.setEncoding('utf8');
  let responseBody = '';

  res.on('data', (chunk) => {
    responseBody += chunk;
  });

  res.on('end', () => {
    console.log('\nResponse:');
    console.log(responseBody);

    if (res.statusCode >= 200 && res.statusCode < 300) {
      console.log('\n✓ Export completed successfully');
    } else {
      console.log(`\n✗ Export failed with status ${res.statusCode}`);
    }
  });
});

req.on('error', (e) => {
  console.error(`\n✗ Request error: ${e.message}`);

  // Provide helpful error messages for common issues
  if (e.code === 'ECONNREFUSED') {
    console.error('The documentation wiki server is not running on localhost:3003');
    console.error('Please start the documentation server and try again.');
  } else if (e.code === 'ENOTFOUND') {
    console.error('Cannot connect to the documentation wiki server.');
    console.error('Please check your network connection and server address.');
  }
});

// Send the data
req.write(postData);
req.end();

