const fs = require('fs');
const http = require('http');

// Read and parse .env.test
const envContent = fs.readFileSync('.env.test', 'utf8');
const envVars = {};

envContent.split('\n').forEach(line => {
  // Skip empty lines and comments
  if (line && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    const value = valueParts.join('=');
    if (key && value !== undefined) {
      envVars[key.trim()] = value.trim();
    }
  }
});

// Prepare JSON payload
const payload = JSON.stringify({
  source: '.env.test',
  environment: 'test',
  variables: envVars,
  exported_at: new Date().toISOString()
}, null, 2);

console.log('Environment variables to be posted:');
console.log(payload);
console.log('\n---\n');

// POST to the endpoint
const postData = payload;
const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = http.request(options, (res) => {
  console.log('Status Code:', res.statusCode);
  console.log('Response Headers:', res.headers);

  let responseBody = '';
  res.on('data', (chunk) => {
    responseBody += chunk;
  });

  res.on('end', () => {
    console.log('Response Body:', responseBody);
    console.log('\n✓ Successfully posted environment variables to documentation endpoint');
  });
});

req.on('error', (err) => {
  console.error('Error posting to endpoint:', err.message);
  console.error('Make sure the server is running on http://localhost:3003');
});

req.write(postData);
req.end();
"

